import * as D from './drills.js';
import {listDrillRecords,getDrillRecord,putDrillRecord,deleteDrillRecord,importDrillRecords} from './drill-db.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,id='',cls='')=>`<button type="button" data-drill="${action}" data-id="${esc(id)}" class="${cls}">${esc(label)}</button>`;
const pct=n=>n==null?'—':Math.round(n*100)+'%',date=s=>new Date(s).toLocaleString();
export function drillWorkspace({main,toast,download,teams,games}){
 let records=[],current=null,folder='',team='',drill='',page=0,queue=Promise.resolve(),active=false,failed=false,pending=0;
 const $=id=>main.querySelector('#'+id);
 const fail=e=>{failed=true;toast('Drill change not saved: '+(e.message||e)+'. Reopen the saved session before continuing.');const status=$('drillSaveStatus');if(status){status.textContent='Not saved · '+(e.message||e);status.classList.add('error-banner');}};
 async function reload(){records=await listDrillRecords();}
 function saveStatus(){const el=$('drillSaveStatus');if(el&&!failed)el.textContent=pending?'Saving '+pending+' drill change'+(pending===1?'':'s')+'…':'All drill changes saved on this device.';}
 function transact(command){pending++;saveStatus();queue=queue.then(async()=>{if(!current)throw Error('Open a drill session first.');if(failed)throw Error('Reopen the saved session before recording more reps.');const next=structuredClone(current);try{command(next);}catch(e){toast(e.message);return null;}const saved=await putDrillRecord(next,current.revision);current=saved;failed=false;records=records.filter(r=>r.id!==saved.id).concat(saved);if(active)render();return saved;}).catch(e=>{fail(e);return null;}).finally(()=>{pending--;saveStatus();});return queue;}
 function heading(){return `<div class="page-heading"><div><span class="eyebrow">Practice workspace</span><h1>Drill library</h1><p>Saved folders, quick rep tracking and progress. Available offline on this device.</p></div><div class="actions">${btn('New drill','new')}${btn('Export '+(folder?'folder':'all drill data'),'export')}${btn('Import drill backup','import')}</div></div>`;}
 function render(){
 if(!active)return;if(current){renderSession();return;}
 const templates=records.filter(r=>r.format===D.formats.template),sessions=records.filter(r=>r.format===D.formats.session),folders=[...new Set(templates.map(t=>t.folder).concat(sessions.map(s=>s.template.folder)))].sort();
 const drills=[...new Map(sessions.map(s=>[s.templateId,s.template.name])).entries()];
 const filtered=sessions.filter(s=>(!folder||s.template.folder===folder)&&(!team||s.team===team)&&(!drill||s.templateId===drill)).sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt)||b.id.localeCompare(a.id)),visible=filtered.slice(page*12,page*12+12),allTeams=[...new Set(sessions.map(s=>s.team))].sort();
 main.innerHTML=heading()+`<section class="surface"><h2>Folders</h2><div class="drill-folders">${btn('All folders','folder','',''+(!folder?'primary':''))}${folders.map(f=>btn(f,'folder',f,f===folder?'primary':'')).join('')}</div><p class="field-note">Folders organize templates and session history inside GameDay. They do not create an automatically synced folder in Files or Google Drive.</p></section><div class="section-heading"><h2>Drill templates${folder?' · '+esc(folder):''}</h2></div><div class="game-grid">${templates.filter(t=>!folder||t.folder===folder).map(t=>`<article class="surface"><span class="eyebrow">${esc(t.folder)}</span><h3>${esc(t.name)}</h3><p>${esc(t.successLabel)} / ${esc(t.failureLabel)} · ${t.tags.length} optional tags</p><div class="actions">${btn('Run drill','run',t.id,'primary')}${btn('View history','history',t.id)}${btn('Delete template','delete-template',t.id,'danger')}</div></article>`).join('')||'<section class="surface"><p>Create your own drill or save one of the starters below.</p></section>'}</div><details class="surface" style="margin-top:18px" ${templates.length?'':'open'}><summary>Starter drills</summary><div class="actions">${D.starters.map((s,i)=>btn('Save '+s.name,'starter',String(i))).join('')}</div></details><div class="section-heading" id="drillHistory"><h2>Saved session history</h2><span>${filtered.length} session${filtered.length===1?'':'s'}</span></div><div class="form-grid"><label>Team filter<select id="drillTeamFilter"><option value="">All teams</option>${allTeams.map(t=>`<option ${t===team?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Drill filter<select id="drillHistoryFilter"><option value="">All drills</option>${drills.map(([id,name])=>`<option value="${esc(id)}" ${id===drill?'selected':''}>${esc(name)}</option>`).join('')}</select></label></div><div class="game-grid" style="margin-top:16px">${visible.map(s=>{const a=D.stats(s);return `<article class="surface"><span class="eyebrow">${esc(s.template.folder)} · ${s.status==='active'?'In progress':'Finished'}</span><h3>${esc(s.template.name)}</h3><p>${esc(s.team)} · ${esc(date(s.startedAt))}</p><p><strong>${a.successes} / ${a.opportunities} · ${pct(a.rate)}</strong> ${esc(s.template.successLabel).toLowerCase()}</p><div class="actions">${btn(s.status==='active'?'Resume':'Open report','open',s.id,'primary')}${btn('Delete','delete-session',s.id,'danger')}</div></article>`;}).join('')||'<section class="surface"><p>No sessions in this view yet. Choose Run drill to start.</p></section>'}</div><div class="actions" style="margin-top:16px">${page?btn('Previous','prev'):''}${(page+1)*12<filtered.length?btn('Next','next'):''}</div><p class="footer-note">Drill records are separate from games. Export a backup to Files / Downloads. Drill backups do not import into CoachIQ’s game-results importer.</p><input type="file" id="drillBackupFile" accept="application/json,.json" hidden>`;
 $('drillHistoryFilter').onchange=e=>{drill=e.target.value;page=0;render();};
 $('drillTeamFilter').onchange=e=>{team=e.target.value;page=0;render();};
 $('drillBackupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Drill backup must be smaller than 8 MB.');const packet=JSON.parse(await file.text()),items=D.readArchive(packet),result=await importDrillRecords(items);await reload();render();toast(result.added+' records imported; '+result.skipped+' existing IDs kept unchanged.');}catch(e){toast(e.message);}};
 }
 function templateForm(seed={}){
 main.innerHTML=`<div class="page-heading"><h1>Create a drill</h1>${btn('Back to library','back')}</div><form id="drillTemplateForm" class="surface"><div class="form-grid"><label>Drill name<input id="drillName" required maxlength="80" value="${esc(seed.name)}"></label><label>Folder<input id="drillFolder" list="drillFolderOptions" required maxlength="60" value="${esc(seed.folder||folder||'General')}"><datalist id="drillFolderOptions">${[...new Set(records.map(r=>r.folder||r.template?.folder))].filter(Boolean).map(f=>`<option value="${esc(f)}">`).join('')}</datalist></label><label>Success button<input id="drillSuccess" required maxlength="30" value="${esc(seed.successLabel||'Success')}"></label><label>Other outcome button<input id="drillFailure" required maxlength="30" value="${esc(seed.failureLabel||'Miss / no score')}"></label><label class="wide">Optional tags · one per line, up to four<textarea id="drillTags" rows="4" placeholder="Paint touch\nOREB\nTurnover">${esc((seed.tags||[]).join('\n'))}</textarea></label><label class="wide"><span><input type="checkbox" id="drillStops" ${seed.defensiveStops?'checked':''}> Success means a defensive stop · count kills (three consecutive stops)</span></label></div><p class="field-note">Each outcome tap saves one opportunity. Tags describe the current rep; finish it with one outcome. Session history keeps the original drill definition.</p><div class="form-footer"><button type="submit" class="primary">Save drill template</button></div></form>`;
 $('drillTemplateForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit.disabled)return;submit.disabled=true;try{const t=D.template({name:$('drillName').value,folder:$('drillFolder').value,successLabel:$('drillSuccess').value,failureLabel:$('drillFailure').value,tags:$('drillTags').value.split('\n').map(s=>s.trim()).filter(Boolean),defensiveStops:$('drillStops').checked});await putDrillRecord(t,0);folder=t.folder;await reload();render();toast('Drill template saved.');}catch(e){toast(e.message);submit.disabled=false;}};
 }
 function startForm(t){
 const teamChoices=teams(),defaultTeam=team||teamChoices[0]||'',seedRoster=chosen=>games().filter(g=>g.team===chosen).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0]?.ourRoster||[];
 main.innerHTML=`<div class="page-heading"><h1>${esc(t.name)}</h1>${btn('Back to library','back')}</div><form id="drillStartForm" class="surface"><div class="form-grid"><label>Team<input id="drillTeam" list="drillTeams" required maxlength="80" value="${esc(defaultTeam)}"><datalist id="drillTeams">${teamChoices.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label><label>Roster · optional, number and name on each line<textarea id="drillRoster" rows="5" placeholder="12, Player Name\n23, Player Name">${esc(seedRoster(defaultTeam).map(p=>p.jersey+', '+p.name).join('\n'))}</textarea></label></div><p class="field-note">Roster is a copy from the latest saved game for the selected team, when available. Confirm it before starting. Leave player blank for team reps.</p><div class="form-footer"><button type="submit" class="primary">Start tracking</button></div></form>`;
 $('drillTeam').onchange=e=>{$('drillRoster').value=seedRoster(e.target.value).map(p=>p.jersey+', '+p.name).join('\n');};
 $('drillStartForm').onsubmit=async e=>{e.preventDefault();if(e.submitter.disabled)return;e.submitter.disabled=true;try{const s=D.session(t,{team:$('drillTeam').value,players:D.roster($('drillRoster').value)});current=await putDrillRecord(s,0);failed=false;await reload();render();}catch(e){toast(e.message);e.submitter.disabled=false;}};
 }
 function report(s,a){
 const trend=D.progress(records,s),fmt=v=>`${v.successes} / ${v.opportunities} · ${pct(v.rate)} (${v.sessions} session${v.sessions===1?'':'s'})`;
 return `<div class="quick-grid"><article class="quick-tile"><h3>${esc(s.template.successLabel)} / opportunities</h3><strong>${a.successes} / ${a.opportunities}</strong><p>${pct(a.rate)}</p></article><article class="quick-tile"><h3>Best success run</h3><strong>${a.bestStreak}</strong><p>${s.template.defensiveStops?a.kills+' kills · '+a.currentStreak+' current stops':'Current run: '+a.currentStreak}</p></article></div><section class="surface"><h3>Tracked actions in completed reps</h3>${s.template.tags.length?s.template.tags.map(label=>{const t=a.tags[label]||{events:0,reps:0,successes:0};return `<p>${esc(label)}: <strong>${t.events} events in ${t.reps} reps</strong> · ${t.successes} / ${t.reps} successful tagged reps</p>`;}).join(''):'<p>No additional tags selected.</p>'}<p class="field-note">Pending tags are excluded until an outcome is saved. Tagged groups overlap. These counts do not prove why a rep succeeded.</p></section><section class="surface"><h3>Player results</h3>${a.players.length?'<div class="table-wrap"><table><thead><tr><th>Player</th><th>Successes / reps</th><th>Rate</th></tr></thead><tbody>'+a.players.map(p=>`<tr><td>#${esc(p.jersey)} ${esc(p.name)}</td><td>${p.successes} / ${p.opportunities}</td><td>${pct(p.successes/p.opportunities)}</td></tr>`).join('')+'</tbody></table></div>':'<p>No individually credited reps yet.</p>'}<small>Unassigned team reps stay in the team total.</small></section><section class="surface"><h3>Progress · same drill and team</h3><p>Latest five finished sessions: <strong>${fmt(trend.recent)}</strong></p><p>Previous five finished sessions: <strong>${fmt(trend.previous)}</strong></p><p class="field-note">Weighted by opportunities. In-progress sessions are excluded. Small samples and changed drill conditions can explain differences.</p></section>`;
 }
 function renderSession(){
 const s=current,a=D.stats(s),live=s.status==='active';main.innerHTML=`<div class="page-heading"><div><span class="eyebrow">${esc(s.template.folder)} · ${esc(s.team)}</span><h1>${esc(s.template.name)}</h1><p>${esc(date(s.startedAt))} · ${live?'In progress':'Finished'}</p></div><div class="actions">${btn('Library','back')}${btn('Export session backup','export-session',s.id)}${live?btn('Finish session','finish',s.id,'primary'):''}</div></div><p id="drillSaveStatus" role="status" class="drill-save-status">${failed?'A change was not saved. Reopen this session.':'All drill changes saved on this device.'}</p>${live?`<section class="surface drill-tracker"><label>Credit this rep to<select id="drillPlayer"><option value="">Team · no player selected</option>${s.players.map(p=>`<option value="${esc(p.jersey)}" ${p.jersey===s.draft.jersey?'selected':''}>#${esc(p.jersey)} ${esc(p.name)}</option>`).join('')}</select></label><div class="possession-bar"><strong>Current rep · ${a.opportunities+1}</strong><p>${Object.entries(s.draft.tags).map(([key,count])=>esc(key)+' × '+count).join(' · ')||'No tags yet'}</p></div><div class="drill-tag-buttons">${s.template.tags.map(label=>btn('+ '+label,'tag',label)).join('')}</div><div class="drill-outcomes">${btn(s.template.successLabel,'success','','mint')}${btn(s.template.failureLabel,'failure','','primary')}</div><div class="actions">${btn('Undo last action','undo')}</div><p class="field-note">Tap tags as needed, then one outcome per rep. Each outcome saves immediately. The selected player stays selected for the next rep.</p></section>`:''}${report(s,a)}<section class="surface"><details><summary>Recent reps · latest ${Math.min(20,a.opportunities)} of ${a.opportunities}</summary><ol>${s.reps.slice(-20).reverse().map((r,i)=>`<li>Rep ${a.opportunities-i}: ${esc(r.success?s.template.successLabel:s.template.failureLabel)}${r.jersey?' · #'+esc(r.jersey):''}${Object.keys(r.tags).length?' · '+Object.entries(r.tags).map(([t,n])=>esc(t)+' × '+n).join(', '):''}</li>`).join('')}</ol></details></section>`;
 saveStatus();
 if(live)$('drillPlayer').onchange=e=>{const jersey=e.target.value;transact(s=>D.selectPlayer(s,jersey));};
 }
 main.addEventListener('click',async e=>{
 const b=e.target.closest('[data-drill]');if(!b||!active)return;const action=b.dataset.drill,id=b.dataset.id;
 try{
 if(action==='success'||action==='failure'){await transact(s=>D.outcome(s,action==='success'));return;}
 if(action==='tag'){await transact(s=>D.tag(s,id));return;}if(action==='undo'){await transact(D.undo);return;}
 await queue;
 if(action==='back'){current=null;await reload();render();}
 else if(action==='folder'){folder=id;drill='';page=0;render();}
 else if(action==='history'){drill=id;page=0;render();$('drillHistory').scrollIntoView({block:'start'});}
 else if(action==='prev'){page=Math.max(0,page-1);render();}else if(action==='next'){page++;render();}
 else if(action==='new')templateForm();
 else if(action==='starter'){const seed=D.starters[Number(id)];if(records.some(r=>r.format===D.formats.template&&r.name===seed.name&&r.folder===seed.folder)){toast('This starter is already saved. Choose Run drill on its template.');return;}b.disabled=true;const t=D.template(seed);await putDrillRecord(t,0);folder=t.folder;await reload();render();}
 else if(action==='run'){const t=await getDrillRecord(id);if(!t||t.format!==D.formats.template)throw Error('Reopen the drill library.');startForm(t);}
 else if(action==='open'){const s=await getDrillRecord(id);D.validate(s);current=s;failed=false;render();}
 else if(action==='finish'){if(!current.reps.length&&!confirm('Finish this session with no recorded reps?'))return;if(await transact(D.finish))toast('Session saved in its drill folder.');}
 else if(action==='export'){download(D.archive(records,folder),'CoachIQ-drills-'+(folder||'all').replace(/[^a-z0-9-]/gi,'-')+'.json');}
 else if(action==='export-session'){download(D.archive([current]),'CoachIQ-drill-session-'+current.id+'.json');}
 else if(action==='import')$('drillBackupFile').click();
 else if(action==='delete-session'||action==='delete-template'){
 const r=records.find(r=>r.id===id);if(!r)return;
 if(!confirm(action==='delete-template'?'Delete this drill template? Its saved session history will remain.':'Delete this drill session from this device? Export a backup first if you need to keep it.'))return;
 await deleteDrillRecord(id,r.revision);await reload();render();toast('Deleted from this device.');
 }
 }catch(e){toast(e.message||String(e));}
 });
 return {async open(){active=true;current=null;page=0;try{await reload();render();}catch(e){main.innerHTML='<section class="surface"><h2>Drill library could not open</h2><p>'+esc(e.message)+'</p></section>';}},async leave(){await queue;active=false;},flush:()=>queue};
}
